use eframe::egui::{self};
#[derive(Clone,Debug)]pub enum ItemKind{Action,Check(bool),Radio(bool),Submenu,Separator}
#[derive(Clone,Debug)]pub struct Item{pub label:String,pub mnemonic:Option<char>,pub shortcut:Option<String>,pub kind:ItemKind,pub enabled:bool,pub action_id:String}
#[derive(Clone,Debug)]pub struct MenuSpec{pub title:String,pub mnemonic:Option<char>,pub items:Vec<Item>}
pub fn show(ui:&mut egui::Ui, menus:&[MenuSpec])->Option<String>{let mut hit=None; ui.horizontal(|ui|{for m in menus{let r=ui.button(&m.title); if r.clicked(){ui.memory_mut(|mem|mem.data.insert_temp(egui::Id::from(("menu",&m.title)),true));} let open=ui.memory(|mem|mem.data.get_temp::<bool>(egui::Id::from(("menu",&m.title))).unwrap_or(false)); if open{egui::Frame::popup(ui.style()).show(ui,|ui|{for i in &m.items{if matches!(i.kind,ItemKind::Separator){ui.separator();continue} let b=ui.add_enabled(i.enabled,egui::Button::new(format!("{}{}",i.label,i.shortcut.as_ref().map(|s|format!("    {s}")).unwrap_or_default())));if b.clicked()&&i.enabled{hit=Some(i.action_id.clone());}}});}}});hit}
#[cfg(test)]mod tests{#[test]fn disabled_item_has_no_action(){assert!(!Item{label:"x".into(),mnemonic:None,shortcut:None,kind:ItemKind::Action,enabled:false,action_id:"x".into()}.enabled);}}
